function make(a,l,r){if(r===5&&!relicGate(l))r=4;let slot=catalog[a][1],p=Math.round((4+l*3)*(1+r*.55)*range(85,115)/100),base={v:[0,0,0,0,0],atk:slot===0?p*2:0,def:slot===1||slot===4?Math.max(1,Math.round(p*.65)):slot===5?Math.round(p*.3):0,hp:slot===2?p*4:slot===4?p*2:0,crit:slot===3?Math.min(.20,Math.round(p*.12)/100):0,pctAtk:0,pctDef:0,pctHp:0},out={...base,v:base.v.slice()},mods=[],count=[1,2,3,4,6,6][r],pre=0,suf=0,used=new Set();for(let j=0;j<count;j++){let pool=affixDefs.map((d,i)=>({d,i})).filter(({d,i})=>!used.has(i)&&kwWeaponAffixAllowed(d,slot,used,l)&&(d[1]==='P'?pre<3:suf<3));if(!pool.length)break;let {d,i}=pick(pool),tier=rollAffixTier(l),roll=range(85,115)/100,value=affixValue(d,l,r,tier,roll);used.add(i);if(d[1]==='P')pre++;else suf++;applyAffix(out,d,value);mods.push({i,tier,roll,value,tierScale:2,effectGate:kwAffixEffectGate(d)});}let relic=null;if(r===5){let gate=relicGate(l),all=gate>=50&&Math.random()<.28,indices=all?[0,1,2,3,4]:pick([[0,3,4],[1,3,4],[2,3,4]]),value=Math.round((gate*4+20)*range(90,110)/100*(all?.70:1));relic={gate,indices,value,all};for(let k of indices){base.v[k]+=value;out.v[k]+=value}}return {id:uid(),a,l,r,p,slot,relic,epithet:r>=2?pick(['','TÜV Edition','Sondermodell','Pfand Deluxe','Garagenfund','Sonderprüfung','Oma Approved','Amtlich fragwürdig','Nachtschicht-Edition',...ITEM_TITLE_VARIANTS.map(row=>row[0])]):'',...out,implicit:base,mods}}

