REGULAR_EXTRA.forEach(r=>{sprites.push(r[7]);catalog.push([r[1],r[0],sprites.length-1]);spriteMap.push(sprites.length-1)});
const REGULAR_POOL=[...Array.from({length:UNIQUE_BASE},(_,i)=>i),...REGULAR_EXTRA.map((_,i)=>REGULAR_EXTRA_START+i)];
function regularBase(){return pick(REGULAR_POOL)}
function isUniqueBase(a){return a>=UNIQUE_BASE&&a<REGULAR_EXTRA_START}

function uniqueMeta(k){return UNIQUE_META[k]||UNIQUE_META[0]}
function uniqueEligibleAtLevel(k,l){let u=UNIQUES[k];if(k<6)return l>=u[3];let phase=k>=RETRO_UNIQUE_FIRST?u[3]:5+5*((k-6)%5);return l>=phase&&((l-phase)%10)<5}
function uniqueWindow(k,l=s.level){if(k<6)return null;let first=k>=RETRO_UNIQUE_FIRST?UNIQUES[k][3]:5+5*((k-6)%5),start=l<first?first:first+10*Math.floor((l-first)/10);if(l>start+4)start+=10;return {start,end:start+4,active:l>=start&&l<=start+4}}
function uniqueWindowText(k){let w=uniqueWindow(k);return w?hubLabel(w.active?'Jetzt im Lootpool':'Nächstes Dropfenster',w.active?'In loot pool now':'Next drop window',w.active?'Сейчас в добыче':'Следующее окно добычи')+' · Lv '+w.start+'–'+w.end:''}
const KW_ORIGINAL_UNIQUE_LORE=[["The dam was approved. By the beaver himself.","Плотину одобрил сам бобр."],["Three hours of streaming. Four seconds of patience.","Три часа стрима. Четыре секунды терпения."],["Chat calls it content. The washing machine calls it overtime.","Чат называет это контентом. Стиралка — переработкой."],["A lifetime subscription. Unfortunately, to a bottle-return machine.","Пожизненная подписка. Увы, на таромат."],["Every key is a comment. None of the comments help.","Каждая клавиша — комментарий. Ни один не помогает."],["Chat says skill issue. The slippers say it's time to clock out.","Чат говорит: скилл ишью. Шлёпанцы говорят: пора домой."],["It looks like peace. It sounds like a comment section at 3 AM.","На вид — мир и покой. На слух — комментарии в три часа ночи."],["One use gives the blocked drain a 24-hour timeout.","Одно применение — и засор отправляется в тайм-аут на сутки."],["Every dent is a reaction. Each reaction is louder than the last.","Каждая вмятина — реакция. И каждая громче предыдущей."],["Your opinion was delivered in person.","Ваше мнение доставлено лично."],["Smells of the sea, anger and unsolicited expertise.","Пахнет морем, злостью и непрошеными экспертными мнениями."],["Three percent left. Enough for a boss fight and two bad decisions.","Осталось три процента. Хватит на босса и два плохих решения."],["Homemade contempt with an extra crunch.","Домашнее презрение с особым хрустом."],["Where this cone stands, reason ends and bureaucracy begins.","Там, где стоит этот конус, кончается здравый смысл и начинается бюрократия."],["Invisible in chat, audible in every garage.","В чате не виден, зато слышен в каждом гараже."],["Reflects sunsets, neon lights and very questionable decisions.","Отражает закаты, неон и весьма сомнительные решения."]];
function uniqueFlavorText(k,lang=s.lang||'de'){let u=UNIQUES[k],meta=uniqueMeta(k),li=lang==='en'?1:lang==='ru'?2:0,row=k>=CROSS_UNIQUE_FIRST?CROSS_ITEM_LORE[k-CROSS_UNIQUE_FIRST]:k>=RETRO_UNIQUE_FIRST?RETRO_UNIQUE_LORE[k-RETRO_UNIQUE_FIRST]:null,txt=row?.[li]??(li?KW_ORIGINAL_UNIQUE_LORE[k]?.[li-1]:u[5])??u[5];return txt+' · '+uniqueBonusText(meta,lang)}
function makeUnique(k,l){let u=UNIQUES[k],meta=uniqueMeta(k);l=Math.max(k<6?u[3]:1,l);let i=make(UNIQUE_BASE+k,l,4);i.r=6;i.unique=k;i.epithet="";let n=k<6?Math.round((l+10)*1.7):Math.max(3,Math.round((l+3)*.85));for(let a of meta.stats){i.v[a]+=n;i.implicit.v[a]+=n}let bonus=meta.bonus,v=meta.value;i[bonus]=(i[bonus]||0)+v;i.implicit[bonus]=(i.implicit[bonus]||0)+v;return i}
